-- ==========================================================================
-- BAGIAN 4: QUERY VERIFIKASI SETELAH EKSEKUSI DI VPS
-- ==========================================================================
-- 4.1 Cek Total Siswa Kelas IX Emerald (Harus Tepat 29 Siswa)
SELECT COUNT(*) AS total_emerald FROM siswa WHERE rombel_id = 68 AND status_siswa = 'Aktif';

-- 4.2 Cek Total Siswa yang Tampil di Dashboard Wali Kelas IX Emerald (Harus Tepat 29 Siswa)
SELECT COUNT(s.id) AS total_tampil_walikelas FROM anggota_rombel ar JOIN siswa s ON s.id = ar.siswa_id WHERE ar.rombel_id = 68 AND s.status_siswa = 'Aktif';

-- 4.3 Cek 5 Siswa yang Baru Dipulihkan Beserta Nilainya
SELECT s.id, s.nis, s.nisn, s.nama_lengkap, s.nik, s.no_hp, s.kelurahan, s.kecamatan, COUNT(DISTINCT nf.id) as jml_nilai_formatif, COUNT(DISTINCT nr.id) as jml_nilai_rapor FROM siswa s LEFT JOIN nilai_formatif nf ON nf.siswa_id = s.id LEFT JOIN nilai_rapor nr ON nr.siswa_id = s.id WHERE s.id IN (138, 140, 141, 143, 145) GROUP BY s.id;

-- 4.4 Cek Apakah Masih Ada Kolom NIK/Kelurahan/Kecamatan/No HP yang Tergeser (Target: 0 Baris)
SELECT COUNT(*) AS sisa_kolom_tergeser FROM siswa WHERE status_siswa = 'Aktif' AND (no_hp = 'Aktif' OR kelurahan LIKE '%SD %' OR kelurahan LIKE '%SMP %' OR nik = nis);